82:   Future<CurrencyPage> _fetchPage(int page) async {
83:     final CurrencyRepository currencyRepository = context.read<CurrencyRepository>();
84:     final CurrencyPage result = await currencyRepository.fetchRates(
85:       CurrencyPageRequest(base: _base, page: page, pageSize: _pageSize),
86:     );
87: 
88:     await currencyRepository.saveCurrencyList(result.items);
89: 
90:     return result;
91:   }
92: 
93:   /// Свежий запрос первой страницы: вызывается при потере фокуса экрана.
94:   Future<void> _reload() async {
95:     final int requestId = ++_requestId;
96:     _isReloading = true;
97: 
98:     try {
99:       final CurrencyPage page = await _fetchPage(0);
100: 
101:       if (!mounted || requestId != _requestId) return;
102: 
103:       _allCurrencies = page.items;
104:       _filteredCurrenciesNotifier.value = page.items;
105:       _lastLoadedPage = page.page;
106:       _hasMore = page.hasMore;
107:     } finally {
108:       _isReloading = false;
109:     }
110:   }
111: 
112:   Future<void> _loadMore() async {
113:     if (_isLoadingMore || !_hasMore) return;
114: 
115:     final int requestId = ++_requestId;
116:     _isLoadingMore = true;
117: 
118:     try {
119:       final CurrencyPage page = await _fetchPage(_lastLoadedPage + 1);
120: 
121:       if (!mounted || requestId != _requestId) return;
122: 
123:       _allCurrencies = [..._allCurrencies, ...page.items];
124:       _filteredCurrenciesNotifier.value = _allCurrencies;
125:       _lastLoadedPage = page.page;
126:       _hasMore = page.hasMore;
127:     } finally {
128:       _isLoadingMore = false;
129:     }
130:   }
