132:   void _filterCurrencies(String query) {
133:     final String lowerQuery = query.toLowerCase();
134:     final Iterable<CurrencyModel> result = _allCurrencies.where((CurrencyModel currency) {
135:       return currency.name.toLowerCase().contains(lowerQuery) || currency.symbol.toLowerCase().contains(lowerQuery);
136:     });
137: 
138:     _filteredCurrenciesNotifier.value = result.toList(growable: true);
139:   }
